package com.muradgalayev.brainbuddy.data.remote

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

@Serializable
data class PreferencesDto(
    @SerialName("user_id")
    val userId: String,
    @SerialName("theme_mode")
    val themeMode: String? = null,
    @SerialName("font_mode")
    val fontMode: String? = null,
    @SerialName("font_size")
    val fontSize: String? = null,
    @SerialName("focus_mode_enabled")
    val focusModeEnabled: Boolean? = null,
    @SerialName("simplified_workspace")
    val simplifiedWorkspace: Boolean? = null,
    @SerialName("enabled_nav_items")
    val enabledNavItems: String? = null
)

package com.muradgalayev.brainbuddy.data.remote

import io.github.jan.supabase.SupabaseClient
import io.github.jan.supabase.postgrest.from
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class SupabasePreferencesDataSource @Inject constructor(
    private val supabaseClient: SupabaseClient
) {
    private val table = "user_preferences"

    suspend fun get(userId: String): PreferencesDto? {
        val list = supabaseClient.from(table)
            .select {
                filter { eq("user_id", userId) }
            }
            .decodeList<PreferencesDto>()
        return list.firstOrNull()
    }

    suspend fun upsert(dto: PreferencesDto) {
        supabaseClient.from(table)
            .upsert(dto)
    }
}

package com.muradgalayev.brainbuddy.data.remote

import com.muradgalayev.brainbuddy.data.remote.dto.TodoItemDto
import io.github.jan.supabase.SupabaseClient
import io.github.jan.supabase.postgrest.from
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class SupabaseTodoDataSource @Inject constructor(
    private val supabaseClient: SupabaseClient
) {
    private val table = "todo_items"

    suspend fun getAll(): List<TodoItemDto> {
        return supabaseClient.from(table)
            .select()
            .decodeList()
    }

    suspend fun upsert(item: TodoItemDto) {
        supabaseClient.from(table)
            .upsert(item)
    }

    suspend fun upsertAll(items: List<TodoItemDto>) {
        if (items.isEmpty()) return
        supabaseClient.from(table)
            .upsert(items)
    }

    suspend fun delete(id: String) {
        supabaseClient.from(table)
            .delete {
                filter { eq("id", id) }
            }
    }
}

package com.muradgalayev.brainbuddy.data.remote

import com.muradgalayev.brainbuddy.data.remote.dto.TodoItemDto
import io.github.jan.supabase.SupabaseClient
import io.github.jan.supabase.postgrest.from
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class SupabaseTodoDataSource @Inject constructor(
    private val supabaseClient: SupabaseClient
) {
    private val table = "todo_items"

    // Fetch only items that belong to the specified userId to avoid mixing data
    // between different Supabase users when syncing.
    suspend fun getAll(userId: String): List<TodoItemDto> {
        // use the actual DB column name (user_id) used by the DTO (@SerialName)
        return supabaseClient.from(table)
            .select {
                filter { eq("user_id", userId) }
            }
            .decodeList()
    }

    suspend fun upsert(item: TodoItemDto) {
        supabaseClient.from(table)
            .upsert(item)
    }

    suspend fun upsertAll(items: List<TodoItemDto>) {
        if (items.isEmpty()) return
        supabaseClient.from(table)
            .upsert(items)
    }

    suspend fun delete(id: String) {
        supabaseClient.from(table)
            .delete {
                filter { eq("id", id) }
            }
    }
}

package com.muradgalayev.brainbuddy.data.repository

import com.muradgalayev.brainbuddy.data.local.PreferencesManager
import com.muradgalayev.brainbuddy.data.local.FontMode
import com.muradgalayev.brainbuddy.data.local.FontSize
import com.muradgalayev.brainbuddy.data.local.ThemeMode
import com.muradgalayev.brainbuddy.data.remote.PreferencesDto
import com.muradgalayev.brainbuddy.data.remote.SupabasePreferencesDataSource
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class PreferencesRepository @Inject constructor(
    private val prefsManager: PreferencesManager,
    private val remote: SupabasePreferencesDataSource,
    private val authRepository: AuthRepository
) {

    private fun getCurrentUserId(): String? = authRepository.getCurrentUserId()

    // Pull remote prefs for current user and apply locally
    suspend fun pullRemoteAndApply() {
        val userId = getCurrentUserId() ?: return
        val dto = remote.get(userId) ?: return
        withContext(Dispatchers.IO) {
            dto.themeMode?.let { prefsManager.setThemeMode(ThemeMode.valueOf(it)) }
            dto.fontMode?.let { prefsManager.setFontMode(FontMode.valueOf(it)) }
            dto.fontSize?.let { prefsManager.setFontSize(FontSize.valueOf(it)) }
            dto.focusModeEnabled?.let { prefsManager.setFocusModeEnabled(it) }
            dto.simplifiedWorkspace?.let { prefsManager.setSimplifiedWorkspace(it) }
            dto.enabledNavItems?.let { raw ->
                val set = if (raw.isBlank()) emptySet() else raw.split(",").toSet()
                prefsManager.setEnabledNavItems(set)
            }
        }
    }

    // Each setter updates local DataStore and pushes the change to Supabase (partial upsert)
    suspend fun setThemeMode(mode: ThemeMode) {
        prefsManager.setThemeMode(mode)
        val userId = getCurrentUserId() ?: return
        remote.upsert(PreferencesDto(userId = userId, themeMode = mode.name))
    }

    suspend fun setFontMode(mode: FontMode) {
        prefsManager.setFontMode(mode)
        val userId = getCurrentUserId() ?: return
        remote.upsert(PreferencesDto(userId = userId, fontMode = mode.name))
    }

    suspend fun setFontSize(size: FontSize) {
        prefsManager.setFontSize(size)
        val userId = getCurrentUserId() ?: return
        remote.upsert(PreferencesDto(userId = userId, fontSize = size.name))
    }

    suspend fun setFocusModeEnabled(enabled: Boolean) {
        prefsManager.setFocusModeEnabled(enabled)
        val userId = getCurrentUserId() ?: return
        remote.upsert(PreferencesDto(userId = userId, focusModeEnabled = enabled))
    }

    suspend fun setSimplifiedWorkspace(enabled: Boolean) {
        prefsManager.setSimplifiedWorkspace(enabled)
        val userId = getCurrentUserId() ?: return
        remote.upsert(PreferencesDto(userId = userId, simplifiedWorkspace = enabled))
    }

    suspend fun setEnabledNavItems(items: Set<String>) {
        prefsManager.setEnabledNavItems(items)
        val userId = getCurrentUserId() ?: return
        val raw = items.joinToString(",")
        remote.upsert(PreferencesDto(userId = userId, enabledNavItems = raw))
    }
}

package com.muradgalayev.brainbuddy.data.repository

import android.util.Log
import com.muradgalayev.brainbuddy.data.local.dao.TodoItemDao
import com.muradgalayev.brainbuddy.data.local.entity.SyncStatus
import com.muradgalayev.brainbuddy.data.mapper.toDomain
import com.muradgalayev.brainbuddy.data.mapper.toDto
import com.muradgalayev.brainbuddy.data.mapper.toEntity
import com.muradgalayev.brainbuddy.data.remote.SupabaseTodoDataSource
import com.muradgalayev.brainbuddy.domain.model.TodoItem
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map
import javax.inject.Inject
import javax.inject.Singleton
import com.muradgalayev.brainbuddy.data.mapper.toEntity as dtoToEntity
import kotlinx.coroutines.flow.emptyFlow

@Singleton
class TodoRepository @Inject constructor(
    private val todoItemDao: TodoItemDao,
    private val remoteDataSource: SupabaseTodoDataSource,
    private val authRepository: AuthRepository
) {
    companion object {
        private const val TAG = "TodoRepository"
    }

    private fun getCurrentUserId(): String? = authRepository.getCurrentUserId()

    // ── Read operations (always from Room, filtered by userId) ──

    fun getAllTodoItems(): Flow<List<TodoItem>> {
        val userId = getCurrentUserId() ?: return emptyFlow()
        return todoItemDao.getAllTodoItems(userId).map { items ->
            items.filter { it.syncStatus != SyncStatus.PENDING_DELETE.name }
                .map { it.toDomain() }
        }
    }

    fun getActiveTodoItems(): Flow<List<TodoItem>> {
        val userId = getCurrentUserId() ?: return emptyFlow()
        return todoItemDao.getActiveTodoItems(userId).map { items ->
            items.filter { it.syncStatus != SyncStatus.PENDING_DELETE.name }
                .map { it.toDomain() }
        }
    }

    fun getCompletedTodoItems(): Flow<List<TodoItem>> {
        val userId = getCurrentUserId() ?: return emptyFlow()
        return todoItemDao.getCompletedTodoItems(userId).map { items ->
            items.filter { it.syncStatus != SyncStatus.PENDING_DELETE.name }
                .map { it.toDomain() }
        }
    }

    fun getTodoItemsByDate(date: String): Flow<List<TodoItem>> {
        val userId = getCurrentUserId() ?: return emptyFlow()
        return todoItemDao.getTodoItemsByDate(date, userId).map { items ->
            items.filter { it.syncStatus != SyncStatus.PENDING_DELETE.name }
                .map { it.toDomain() }
        }
    }

    fun getTodoItemsInRange(startDate: String, endDate: String): Flow<List<TodoItem>> {
        val userId = getCurrentUserId() ?: return emptyFlow()
        return todoItemDao.getTodoItemsInRange(startDate, endDate, userId).map { items ->
            items.filter { it.syncStatus != SyncStatus.PENDING_DELETE.name }
                .map { it.toDomain() }
        }
    }

    suspend fun getTodoItemById(id: String): TodoItem? {
        val userId = getCurrentUserId() ?: return null
        return todoItemDao.getTodoItemById(id, userId)?.toDomain()
    }

    // ── Write operations ──

    suspend fun insertTodoItem(todoItem: TodoItem) {
        val userId = getCurrentUserId() ?: return
        val entity = todoItem.toEntity(userId).copy(
            syncStatus = SyncStatus.PENDING_INSERT.name,
            lastModifiedAt = System.currentTimeMillis()
        )
        todoItemDao.insertTodoItem(entity)
        tryRemoteUpsert(entity)
    }

    suspend fun updateTodoItem(todoItem: TodoItem) {
        val userId = getCurrentUserId() ?: return
        val entity = todoItem.toEntity(userId).copy(
            syncStatus = SyncStatus.PENDING_UPDATE.name,
            lastModifiedAt = System.currentTimeMillis()
        )
        todoItemDao.updateTodoItem(entity)
        tryRemoteUpsert(entity)
    }

    suspend fun deleteTodoItem(todoItem: TodoItem) {
        val userId = getCurrentUserId() ?: return
        val entity = todoItem.toEntity(userId).copy(
            syncStatus = SyncStatus.PENDING_DELETE.name
        )
        todoItemDao.updateTodoItem(entity)
        tryRemoteDelete(entity.id, userId)
    }

    suspend fun toggleTodoItemCompletion(id: String) {
        val userId = getCurrentUserId() ?: return
        val item = todoItemDao.getTodoItemById(id, userId) ?: return
        val updated = item.copy(
            isCompleted = !item.isCompleted,
            syncStatus = SyncStatus.PENDING_UPDATE.name,
            lastModifiedAt = System.currentTimeMillis()
        )
        todoItemDao.updateTodoItem(updated)
        tryRemoteUpsert(updated)
    }

    // ── Sync operations ──

    suspend fun sync() {
        val userId = getCurrentUserId() ?: return
        try {
            pushPendingChanges(userId)
            pullRemoteChanges(userId)
        } catch (e: Exception) {
            Log.w(TAG, "Sync failed: ${e.message}")
        }
    }

    private suspend fun pushPendingChanges(userId: String) {
        val pendingItems = todoItemDao.getPendingSyncItems(userId)

        for (item in pendingItems) {
            try {
                when (item.syncStatus) {
                    SyncStatus.PENDING_INSERT.name,
                    SyncStatus.PENDING_UPDATE.name -> {
                        remoteDataSource.upsert(item.toDto(userId))
                        todoItemDao.updateSyncStatus(item.id, userId, SyncStatus.SYNCED.name)
                    }
                    SyncStatus.PENDING_DELETE.name -> {
                        remoteDataSource.delete(item.id)
                        todoItemDao.deleteById(item.id, userId)
                    }
                }
            } catch (e: Exception) {
                Log.w(TAG, "Failed to sync item ${item.id}: ${e.message}")
            }
        }
    }

    private suspend fun pullRemoteChanges(userId: String) {
        try {
            val remoteItems = remoteDataSource.getAll()
            val pendingItems = todoItemDao.getPendingSyncItems(userId)
            val pendingIds = pendingItems.map { it.id }.toSet()

            for (remoteItem in remoteItems) {
                if (remoteItem.id !in pendingIds) {
                    todoItemDao.insertTodoItem(remoteItem.dtoToEntity().copy(userId = userId))
                }
            }
        } catch (e: Exception) {
            Log.w(TAG, "Failed to pull remote changes: ${e.message}")
        }
    }

    private suspend fun tryRemoteUpsert(
        entity: com.muradgalayev.brainbuddy.data.local.entity.TodoItemEntity
    ) {
        try {
            val userId = getCurrentUserId() ?: return
            remoteDataSource.upsert(entity.toDto(userId))
            todoItemDao.updateSyncStatus(entity.id, userId, SyncStatus.SYNCED.name)
        } catch (e: Exception) {
            Log.w(TAG, "Remote upsert failed, will sync later: ${e.message}")
        }
    }

    private suspend fun tryRemoteDelete(id: String, userId: String) {
        try {
            remoteDataSource.delete(id)
            todoItemDao.deleteById(id, userId)
        } catch (e: Exception) {
            Log.w(TAG, "Remote delete failed, will sync later: ${e.message}")
        }
    }
}

package com.muradgalayev.brainbuddy.data.repository

import android.util.Log
import com.muradgalayev.brainbuddy.data.local.dao.TodoItemDao
import com.muradgalayev.brainbuddy.data.local.entity.SyncStatus
import com.muradgalayev.brainbuddy.data.mapper.toDomain
import com.muradgalayev.brainbuddy.data.mapper.toDto
import com.muradgalayev.brainbuddy.data.mapper.toEntity
import com.muradgalayev.brainbuddy.data.remote.SupabaseTodoDataSource
import com.muradgalayev.brainbuddy.domain.model.TodoItem
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map
import javax.inject.Inject
import javax.inject.Singleton
import com.muradgalayev.brainbuddy.data.mapper.toEntity as dtoToEntity
import kotlinx.coroutines.flow.emptyFlow

@Singleton
class TodoRepository @Inject constructor(
    private val todoItemDao: TodoItemDao,
    private val remoteDataSource: SupabaseTodoDataSource,
    private val authRepository: AuthRepository
) {
    companion object {
        private const val TAG = "TodoRepository"
    }

    private fun getCurrentUserId(): String? = authRepository.getCurrentUserId()

    // ── Read operations (always from Room, filtered by userId) ──

    fun getAllTodoItems(): Flow<List<TodoItem>> {
        val userId = getCurrentUserId() ?: return emptyFlow()
        return todoItemDao.getAllTodoItems(userId).map { items ->
            items.filter { it.syncStatus != SyncStatus.PENDING_DELETE.name }
                .map { it.toDomain() }
        }
    }

    fun getActiveTodoItems(): Flow<List<TodoItem>> {
        val userId = getCurrentUserId() ?: return emptyFlow()
        return todoItemDao.getActiveTodoItems(userId).map { items ->
            items.filter { it.syncStatus != SyncStatus.PENDING_DELETE.name }
                .map { it.toDomain() }
        }
    }

    fun getCompletedTodoItems(): Flow<List<TodoItem>> {
        val userId = getCurrentUserId() ?: return emptyFlow()
        return todoItemDao.getCompletedTodoItems(userId).map { items ->
            items.filter { it.syncStatus != SyncStatus.PENDING_DELETE.name }
                .map { it.toDomain() }
        }
    }

    fun getTodoItemsByDate(date: String): Flow<List<TodoItem>> {
        val userId = getCurrentUserId() ?: return emptyFlow()
        return todoItemDao.getTodoItemsByDate(date, userId).map { items ->
            items.filter { it.syncStatus != SyncStatus.PENDING_DELETE.name }
                .map { it.toDomain() }
        }
    }

    fun getTodoItemsInRange(startDate: String, endDate: String): Flow<List<TodoItem>> {
        val userId = getCurrentUserId() ?: return emptyFlow()
        return todoItemDao.getTodoItemsInRange(startDate, endDate, userId).map { items ->
            items.filter { it.syncStatus != SyncStatus.PENDING_DELETE.name }
                .map { it.toDomain() }
        }
    }

    suspend fun getTodoItemById(id: String): TodoItem? {
        val userId = getCurrentUserId() ?: return null
        return todoItemDao.getTodoItemById(id, userId)?.toDomain()
    }

    // ── Write operations ──

    suspend fun insertTodoItem(todoItem: TodoItem) {
        val userId = getCurrentUserId() ?: return
        val entity = todoItem.toEntity(userId).copy(
            syncStatus = SyncStatus.PENDING_INSERT.name,
            lastModifiedAt = System.currentTimeMillis()
        )
        todoItemDao.insertTodoItem(entity)
        tryRemoteUpsert(entity)
    }

    suspend fun updateTodoItem(todoItem: TodoItem) {
        val userId = getCurrentUserId() ?: return
        val entity = todoItem.toEntity(userId).copy(
            syncStatus = SyncStatus.PENDING_UPDATE.name,
            lastModifiedAt = System.currentTimeMillis()
        )
        todoItemDao.updateTodoItem(entity)
        tryRemoteUpsert(entity)
    }

    suspend fun deleteTodoItem(todoItem: TodoItem) {
        val userId = getCurrentUserId() ?: return
        val entity = todoItem.toEntity(userId).copy(
            syncStatus = SyncStatus.PENDING_DELETE.name
        )
        todoItemDao.updateTodoItem(entity)
        tryRemoteDelete(entity.id, userId)
    }

    suspend fun toggleTodoItemCompletion(id: String) {
        val userId = getCurrentUserId() ?: return
        val item = todoItemDao.getTodoItemById(id, userId) ?: return
        val updated = item.copy(
            isCompleted = !item.isCompleted,
            syncStatus = SyncStatus.PENDING_UPDATE.name,
            lastModifiedAt = System.currentTimeMillis()
        )
        todoItemDao.updateTodoItem(updated)
        tryRemoteUpsert(updated)
    }

    // ── Sync operations ──

    suspend fun sync() {
        val userId = getCurrentUserId() ?: return
        try {
            pushPendingChanges(userId)
            pullRemoteChanges(userId)
        } catch (e: Exception) {
            Log.w(TAG, "Sync failed: ${e.message}")
        }
    }

    private suspend fun pushPendingChanges(userId: String) {
        val pendingItems = todoItemDao.getPendingSyncItems(userId)

        for (item in pendingItems) {
            try {
                when (item.syncStatus) {
                    SyncStatus.PENDING_INSERT.name,
                    SyncStatus.PENDING_UPDATE.name -> {
                        remoteDataSource.upsert(item.toDto(userId))
                        todoItemDao.updateSyncStatus(item.id, userId, SyncStatus.SYNCED.name)
                    }
                    SyncStatus.PENDING_DELETE.name -> {
                        remoteDataSource.delete(item.id)
                        todoItemDao.deleteById(item.id, userId)
                    }
                }
            } catch (e: Exception) {
                Log.w(TAG, "Failed to sync item ${item.id}: ${e.message}")
            }
        }
    }

    private suspend fun pullRemoteChanges(userId: String) {
        try {
            // Only pull remote items for the currently authenticated user
            val remoteItems = remoteDataSource.getAll(userId)
            val pendingItems = todoItemDao.getPendingSyncItems(userId)
            val pendingIds = pendingItems.map { it.id }.toSet()

            for (remoteItem in remoteItems) {
                if (remoteItem.id !in pendingIds) {
                    todoItemDao.insertTodoItem(remoteItem.dtoToEntity().copy(userId = userId))
                }
            }
        } catch (e: Exception) {
            Log.w(TAG, "Failed to pull remote changes: ${e.message}")
        }
    }

    private suspend fun tryRemoteUpsert(
        entity: com.muradgalayev.brainbuddy.data.local.entity.TodoItemEntity
    ) {
        try {
            val userId = getCurrentUserId() ?: return
            remoteDataSource.upsert(entity.toDto(userId))
            todoItemDao.updateSyncStatus(entity.id, userId, SyncStatus.SYNCED.name)
        } catch (e: Exception) {
            Log.w(TAG, "Remote upsert failed, will sync later: ${e.message}")
        }
    }

    private suspend fun tryRemoteDelete(id: String, userId: String) {
        try {
            remoteDataSource.delete(id)
            todoItemDao.deleteById(id, userId)
        } catch (e: Exception) {
            Log.w(TAG, "Remote delete failed, will sync later: ${e.message}")
        }
    }

    // Clear local data for a specific user (used on sign out to avoid leaking tasks
    // between different accounts on the same device).
    suspend fun clearLocalForUser(userId: String) {
        todoItemDao.deleteAllForUser(userId)
    }
}

package com.muradgalayev.brainbuddy.ui.auth

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.muradgalayev.brainbuddy.data.repository.AuthRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import javax.inject.Inject

data class AuthUiState(
    val firstName: String = "",
    val lastName: String = "",
    val phone: String = "",
    val email: String = "",
    val password: String = "",
    val isLoginMode: Boolean = true,
    val isLoading: Boolean = false,
    val error: String? = null,
    val isSuccess: Boolean = false
)

@HiltViewModel
class AuthViewModel @Inject constructor(
    private val authRepository: AuthRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(AuthUiState())
    val uiState: StateFlow<AuthUiState> = _uiState.asStateFlow()

    fun onFirstNameChanged(value: String) {
        _uiState.update { it.copy(firstName = value, error = null) }
    }

    fun onLastNameChanged(value: String) {
        _uiState.update { it.copy(lastName = value, error = null) }
    }

    fun onPhoneChanged(value: String) {
        _uiState.update { it.copy(phone = value, error = null) }
    }

    fun onEmailChanged(email: String) {
        _uiState.update { it.copy(email = email, error = null) }
    }

    fun onPasswordChanged(password: String) {
        _uiState.update { it.copy(password = password, error = null) }
    }

    fun toggleMode() {
        _uiState.update { it.copy(isLoginMode = !it.isLoginMode, error = null) }
    }

    fun submit() {
        val state = _uiState.value
        if (state.email.isBlank() || state.password.isBlank()) {
            _uiState.update { it.copy(error = "Please fill in all fields") }
            return
        }
        if (!state.isLoginMode && (state.firstName.isBlank() || state.lastName.isBlank())) {
            _uiState.update { it.copy(error = "Please enter your name") }
            return
        }
        if (state.password.length < 6) {
            _uiState.update { it.copy(error = "Password must be at least 6 characters") }
            return
        }

        _uiState.update { it.copy(isLoading = true, error = null) }

        viewModelScope.launch {
            try {
                if (state.isLoginMode) {
                    authRepository.signIn(state.email.trim(), state.password)
                } else {
                    authRepository.signUp(
                        email = state.email.trim(),
                        password = state.password,
                        firstName = state.firstName.trim(),
                        lastName = state.lastName.trim(),
                        phone = state.phone.trim()
                    )
                }
                _uiState.update { it.copy(isLoading = false, isSuccess = true) }
            } catch (e: Exception) {
                val message = when {
                    e.message?.contains("Invalid login", ignoreCase = true) == true ->
                        "Invalid email or password"
                    e.message?.contains("already registered", ignoreCase = true) == true ->
                        "This email is already registered"
                    e.message?.contains("valid email", ignoreCase = true) == true ->
                        "Please enter a valid email address"
                    else -> e.message ?: "Something went wrong"
                }
                _uiState.update { it.copy(isLoading = false, error = message) }
            }
        }
    }
}

package com.muradgalayev.brainbuddy.ui.auth

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.muradgalayev.brainbuddy.data.repository.AuthRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import javax.inject.Inject

data class AuthUiState(
    val firstName: String = "",
    val lastName: String = "",
    val phone: String = "",
    val email: String = "",
    val password: String = "",
    val isLoginMode: Boolean = true,
    val isLoading: Boolean = false,
    val error: String? = null,
    val isSuccess: Boolean = false
)

@HiltViewModel
class AuthViewModel @Inject constructor(
    private val authRepository: AuthRepository,
    private val todoRepository: com.muradgalayev.brainbuddy.data.repository.TodoRepository,
    private val preferencesRepository: com.muradgalayev.brainbuddy.data.repository.PreferencesRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(AuthUiState())
    val uiState: StateFlow<AuthUiState> = _uiState.asStateFlow()

    fun onFirstNameChanged(value: String) {
        _uiState.update { it.copy(firstName = value, error = null) }
    }

    fun onLastNameChanged(value: String) {
        _uiState.update { it.copy(lastName = value, error = null) }
    }

    fun onPhoneChanged(value: String) {
        _uiState.update { it.copy(phone = value, error = null) }
    }

    fun onEmailChanged(email: String) {
        _uiState.update { it.copy(email = email, error = null) }
    }

    fun onPasswordChanged(password: String) {
        _uiState.update { it.copy(password = password, error = null) }
    }

    fun toggleMode() {
        _uiState.update { it.copy(isLoginMode = !it.isLoginMode, error = null) }
    }

    fun submit() {
        val state = _uiState.value
        if (state.email.isBlank() || state.password.isBlank()) {
            _uiState.update { it.copy(error = "Please fill in all fields") }
            return
        }
        if (!state.isLoginMode && (state.firstName.isBlank() || state.lastName.isBlank())) {
            _uiState.update { it.copy(error = "Please enter your name") }
            return
        }
        if (state.password.length < 6) {
            _uiState.update { it.copy(error = "Password must be at least 6 characters") }
            return
        }

        _uiState.update { it.copy(isLoading = true, error = null) }

        viewModelScope.launch {
            try {
                if (state.isLoginMode) {
                    authRepository.signIn(state.email.trim(), state.password)
                } else {
                    authRepository.signUp(
                        email = state.email.trim(),
                        password = state.password,
                        firstName = state.firstName.trim(),
                        lastName = state.lastName.trim(),
                        phone = state.phone.trim()
                    )
                }
                // After successful authentication, pull remote tasks and preferences for this user
                todoRepository.sync()
                preferencesRepository.pullRemoteAndApply()
                _uiState.update { it.copy(isLoading = false, isSuccess = true) }
            } catch (e: Exception) {
                val message = when {
                    e.message?.contains("Invalid login", ignoreCase = true) == true ->
                        "Invalid email or password"
                    e.message?.contains("already registered", ignoreCase = true) == true ->
                        "This email is already registered"
                    e.message?.contains("valid email", ignoreCase = true) == true ->
                        "Please enter a valid email address"
                    else -> e.message ?: "Something went wrong"
                }
                _uiState.update { it.copy(isLoading = false, error = message) }
            }
        }
    }
}

package com.muradgalayev.brainbuddy.ui.settings

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.muradgalayev.brainbuddy.data.local.FontMode
import com.muradgalayev.brainbuddy.data.local.FontSize
import com.muradgalayev.brainbuddy.data.local.PreferencesManager
import com.muradgalayev.brainbuddy.data.local.ThemeMode
import com.muradgalayev.brainbuddy.data.repository.AuthRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch
import javax.inject.Inject

@HiltViewModel
class SettingsViewModel @Inject constructor(
    private val preferencesManager: PreferencesManager,
    private val authRepository: AuthRepository
) : ViewModel() {

    private val _loggedOut = MutableStateFlow(false)
    val loggedOut: StateFlow<Boolean> = _loggedOut.asStateFlow()

    val userEmail: String?
        get() = authRepository.getCurrentUserEmail()

    val userFullName: String?
        get() = authRepository.getCurrentUserFullName()

    val fontSize = preferencesManager.fontSize
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), FontSize.Medium)
    val themeMode = preferencesManager.themeMode
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), ThemeMode.System)

    val fontMode = preferencesManager.fontMode
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), FontMode.Classic)

    val enabledNavItems = preferencesManager.enabledNavItems
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptySet())

    val focusModeEnabled = preferencesManager.focusModeEnabled
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), false)

    val simplifiedWorkspace = preferencesManager.simplifiedWorkspace
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), false)

    fun setThemeMode(mode: ThemeMode) {
        viewModelScope.launch { preferencesManager.setThemeMode(mode) }
    }

    fun setFontMode(mode: FontMode) {
        viewModelScope.launch { preferencesManager.setFontMode(mode) }
    }

    fun toggleNavItem(route: String, enabled: Boolean) {
        viewModelScope.launch { preferencesManager.setNavItemEnabled(route, enabled) }
    }

    fun toggleFocusMode(enabled: Boolean) {
        viewModelScope.launch { preferencesManager.setFocusModeEnabled(enabled) }
    }

    fun toggleSimplifiedWorkspace(enabled: Boolean) {
        viewModelScope.launch { preferencesManager.setSimplifiedWorkspace(enabled) }
    }
    fun setFontSize(fontSize: FontSize) {
        viewModelScope.launch {
            preferencesManager.setFontSize(fontSize)
        }
    }

    fun signOut() {
        viewModelScope.launch {
            authRepository.signOut()
            _loggedOut.value = true
        }
    }
}

package com.muradgalayev.brainbuddy.ui.settings

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.muradgalayev.brainbuddy.data.local.FontMode
import com.muradgalayev.brainbuddy.data.local.FontSize
import com.muradgalayev.brainbuddy.data.local.PreferencesManager
import com.muradgalayev.brainbuddy.data.local.ThemeMode
import com.muradgalayev.brainbuddy.data.repository.AuthRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.flow.firstOrNull
import kotlinx.coroutines.launch
import javax.inject.Inject

@HiltViewModel
class SettingsViewModel @Inject constructor(
    private val preferencesManager: PreferencesManager,
    private val authRepository: AuthRepository,
    private val todoRepository: com.muradgalayev.brainbuddy.data.repository.TodoRepository,
    private val preferencesRepository: com.muradgalayev.brainbuddy.data.repository.PreferencesRepository
) : ViewModel() {

    private val _loggedOut = MutableStateFlow(false)
    val loggedOut: StateFlow<Boolean> = _loggedOut.asStateFlow()

    val userEmail: String?
        get() = authRepository.getCurrentUserEmail()

    val userFullName: String?
        get() = authRepository.getCurrentUserFullName()

    val fontSize = preferencesManager.fontSize
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), FontSize.Medium)
    val themeMode = preferencesManager.themeMode
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), ThemeMode.System)

    val fontMode = preferencesManager.fontMode
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), FontMode.Classic)

    val enabledNavItems = preferencesManager.enabledNavItems
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptySet())

    val focusModeEnabled = preferencesManager.focusModeEnabled
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), false)

    val simplifiedWorkspace = preferencesManager.simplifiedWorkspace
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), false)

    fun setThemeMode(mode: ThemeMode) {
        viewModelScope.launch { preferencesRepository.setThemeMode(mode) }
    }

    fun setFontMode(mode: FontMode) {
        viewModelScope.launch { preferencesRepository.setFontMode(mode) }
    }

    fun toggleNavItem(route: String, enabled: Boolean) {
        viewModelScope.launch {
            // update local set fully via repository
            // read the current set once and compute the new set
            val set = preferencesManager.enabledNavItems.firstOrNull() ?: emptySet()
            val newSet = if (enabled) set + route else set - route
            preferencesRepository.setEnabledNavItems(newSet)
        }
    }

    fun toggleFocusMode(enabled: Boolean) {
        viewModelScope.launch { preferencesRepository.setFocusModeEnabled(enabled) }
    }

    fun toggleSimplifiedWorkspace(enabled: Boolean) {
        viewModelScope.launch { preferencesRepository.setSimplifiedWorkspace(enabled) }
    }
    fun setFontSize(fontSize: FontSize) {
        viewModelScope.launch {
            preferencesRepository.setFontSize(fontSize)
        }
    }

    fun signOut() {
        viewModelScope.launch {
            // capture current user id before signing out
            val currentUserId = authRepository.getCurrentUserId()
            authRepository.signOut()
            currentUserId?.let {
                // clear local tasks for the user that just signed out
                todoRepository.clearLocalForUser(it)
            }
            _loggedOut.value = true
        }
    }
}
